#!/bin/sh
# Build the .deb and .rpm packages of wtm into target/packages.
#
# Needs: a Rust toolchain with the target installed, a C compiler for it
# (musl-tools for the default musl target), cargo-deb and
# cargo-generate-rpm. packaging/docker-build.sh runs this in a container
# with all of that.
set -eu
cd "$(dirname "$0")/.."

target=${1:-x86_64-unknown-linux-musl}
bin=target/$target/release/wtm

cargo build --release --locked -p wtm --target "$target"
strip "$bin" 2>/dev/null || true

# Man pages and completion files, generated by the binary itself.
rm -rf target/assets
mkdir -p target/assets/man target/assets/completions
"$bin" generate man target/assets/man
gzip -9n target/assets/man/*.1
"$bin" generate completion bash > target/assets/completions/wtm.bash
"$bin" generate completion zsh > target/assets/completions/_wtm

rm -rf target/packages
mkdir -p target/packages
cargo deb -p wtm --target "$target" --no-build --no-strip -o target/packages/
cargo generate-rpm -p wtm --target "$target" -o target/packages/
ls -l target/packages
